import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, vec4, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the pricing card label
  const group = new THREE.Group();
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Backdrop plane: engineered gradient surface with subtle grain
  const backdropGeo = new THREE.PlaneGeometry(2.4, 0.5);

  // Create node-based material with gradient + grain
  const uvNode = uv();
  const gradientNode = mix(
    color(config.intent?.visualSpec?.colors?.ink || '#16161d'),
    color(config.intent?.visualSpec?.colors?.surface || '#0b0b10'),
    uvNode.y
  );

  // Subtle grain via noise-like modulation
  const grainNode = mix(
    vec3(0.98),
    vec3(1.02),
    vec4(Math.random() * 0.1)
  );

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(gradientNode, grainNode, 0.08),
    toneMapped: true,
  });

  const backdropMesh = new THREE.Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -0.01;
  group.add(backdropMesh);

  // Text label: "Pricing 1"
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const pricingLabel = textItems.find(item => item.text && item.text.includes('Pricing'));

  if (pricingLabel || textItems.length > 0) {
    const labelText = pricingLabel?.text || 'Pricing 1';
    const labelFontSize = pricingLabel?.typography?.fontSize || 39;

    const textMesh = ctx.fontAtlas.createText(labelText, {
      fontSize: labelFontSize,
      color: config.intent?.visualSpec?.colors?.paper || '#e8ecf2',
      align: 'center',
      maxWidthPx: 320,
    });

    textMesh.position.set(0, 0, 0.02);
    group.add(textMesh);
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    backdropGeo.dispose();
    backdropMat.dispose();
    group.children.forEach(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  group.userData.handlers = {};

  return group;
}
